-- Final Tommy Fix cleanup: remove every grouped wholesale range card and restore each known variant as its own product.
DELETE FROM catalogue_products WHERE name LIKE 'TOMMY FIX%' AND (code LIKE 'WHPDF-CARD-P09-%' OR code LIKE 'WHPDF-CARD-P10F-%');
DELETE FROM catalogue_products WHERE code IN ('WHPDF-CARD-P09-20','WHPDF-CARD-P09-21');

-- Reapply the individual-code data in case earlier migrations were already marked applied on the remote database.
-- Restore Tommy Fix items as individual code products instead of grouped range cards
DELETE FROM catalogue_products WHERE code IN ('WHPDF-CARD-P09-20','WHPDF-CARD-P09-21','WHPDF-CARD-P09-22','WHPDF-CARD-P09-23','WHPDF-CARD-P09-24','WHPDF-CARD-P09-25','WHPDF-CARD-P10F-01','WHPDF-CARD-P10F-02','WHPDF-CARD-P10F-03','WHPDF-CARD-P10F-04','WHPDF-CARD-P10F-05','WHPDF-CARD-P10F-06','WHPDF-CARD-P10F-07','WHPDF-CARD-P10F-08','WHPDF-CARD-P10F-09');
DELETE FROM catalogue_products WHERE created_by='system:wholesale-original-pdf-v2' AND name LIKE 'TOMMY FIX%';
